    """Tests for the qualifies_for_bulk_discount function."""

    @pytest.mark.l4("C-8764baca")
    def test_quantity_exactly_10_qualifies(self):
        """WHEN a line item has a quantity of exactly 10 THEN it qualifies."""
        item = LineItem("widget", Decimal("1.00"), 10)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-e4015f6b")
    def test_quantity_greater_than_10_qualifies(self):
        """WHEN a line item has a quantity greater than 10 THEN it qualifies."""
        item = LineItem("widget", Decimal("1.00"), 15)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-4284227d")
    def test_quantity_9_does_not_qualify(self):
        """WHEN a line item has a quantity of 9 THEN it does not qualify."""
        item = LineItem("widget", Decimal("1.00"), 9)
        assert qualifies_for_bulk_discount(item) is False

    @pytest.mark.l4("C-4284227d")
    def test_quantity_below_9_does_not_qualify(self):
        """WHEN a line item has a quantity below 9 THEN it does not qualify."""
        item = LineItem("widget", Decimal("1.00"), 5)
        assert qualifies_for_bulk_discount(item) is False


class TestCalculateBulkDiscount:
    """Tests for the calculate_bulk_discount function."""

    @pytest.mark.l4("C-8764baca")
    def test_discount_for_quantity_exactly_10(self):
        """WHEN quantity is exactly 10 THEN 5% discount is applied."""
        item = LineItem("widget", Decimal("1.00"), 10)
        # 10 * 1.00 = 10.00, 5% = 0.50
        assert calculate_bulk_discount(item) == Decimal("0.50")

    @pytest.mark.l4("C-e4015f6b")
    def test_discount_for_quantity_greater_than_10(self):
        """WHEN quantity is greater than 10 THEN 5% discount is applied."""
        item = LineItem("widget", Decimal("1.00"), 15)
        # 15 * 1.00 = 15.00, 5% = 0.75
        assert calculate_bulk_discount(item) == Decimal("0.75")

    @pytest.mark.l4("C-4284227d")
    def test_no_discount_for_quantity_9(self):
        """WHEN quantity is 9 THEN no discount is applied."""
        item = LineItem("widget", Decimal("1.00"), 9)
        assert calculate_bulk_discount(item) == Decimal("0.00")

    @pytest.mark.l4("C-4284227d")
    def test_no_discount_for_quantity_below_threshold(self):
        """WHEN quantity is below threshold THEN no discount is applied."""
        item = LineItem("widget", Decimal("5.00"), 3)
        assert calculate_bulk_discount(item) == Decimal("0.00")

    @pytest.mark.l4("C-1caf4da3")
    def test_rounding_half_up(self):
        """WHEN discount requires rounding THEN half-up rounding is used."""
        # 10 * 1.00 = 10.00, 5% = 0.50
        # Let's use a case that requires rounding: 10 items at 0.25 = 2.50, 5% = 0.125 -> 0.13
        item = LineItem("widget", Decimal("0.25"), 10)
