    def test_rounding_half_up_exact_cent(self):
        """WHEN discount is already at cent precision THEN no rounding needed."""
        item = LineItem("widget", Decimal("2.00"), 10)
        # 10 * 2.00 = 20.00, 5% = 1.00
        assert calculate_bulk_discount(item) == Decimal("1.00")


class TestBulkDiscountConstants:
    """Tests for bulk discount constants."""

    @pytest.mark.l4("C-8764baca")
    def test_bulk_quantity_threshold_is_10(self):
        """The threshold for bulk discount is 10 items."""
        assert BULK_QUANTITY_THRESHOLD == 10

    @pytest.mark.l4("C-8764baca")
